INSERT INTO feature VALUES('host-entropy','runtime','Fair bits from the host''s entropy over `std.rand.Eff`','host-effects','implemented','ordinary',NULL,'The host interface `std.rand.Eff` draws an integer uniform over `[0, 2^n)` for a width `n` from 1 to 64; `gandr run` answers each `draw` from the entropy source of the operating system, eight bytes a draw and no state between draws, so a run that never draws never reads the source. A handler written in the language answers the same draws as a second model of `std.rand.Eff`: from a fixed list, or from a seed by `std.rand.lcg`, a linear congruential generator in std that sends each draw it cannot answer to the model outside it. A width outside that range, or a source that fails, is declined with its cause on standard error, and the run is stuck at it.','core-term surface-dispatcher surface-driver','corpus/model/probability/draws.gandr crates/surface-dispatcher/tests/run.rs crates/surface-driver/tests/rand.rs corpus/model/probability/seeded.gandr','corpus/model/probability/draws.gandr',NULL);
